import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { QrCode, Download, LockKeyhole } from "lucide-react";

/**
 * Separate, account-protected QR/PDF for an individual workspace priority.
 * This does not alter the site's existing QR/assistant functionality.
 * QR PNG and PDF are generated by the authenticated workspace endpoints.
 */
export default function PriorityQrPdf({ kind, itemId, expandedInitially = false, testId = "workspace-qrpdf" }) {
  const [expanded, setExpanded] = useState(expandedInitially);
  const [qrSrc, setQrSrc] = useState("");
  const [qrError, setQrError] = useState("");
  const [busy, setBusy] = useState(false);
  const [pdfError, setPdfError] = useState("");

  const base = `${process.env.REACT_APP_BACKEND_URL || ""}/api/workspace/priorities/${kind}/${encodeURIComponent(itemId || "")}`;
  const detailPath = `/area/priorita/${kind}/${encodeURIComponent(itemId || "")}`;

  useEffect(() => {
    setExpanded(expandedInitially);
    setQrSrc("");
    setQrError("");
    setPdfError("");
  }, [kind, itemId, expandedInitially]);

  useEffect(() => {
    if (!expanded || !itemId) return;
    let active = true;
    let objectUrl = "";
    setQrSrc("");
    setQrError("");
    fetch(`${base}/qr`, {
      headers: { Authorization: `Bearer ${localStorage.getItem("da_token") || ""}` },
      cache: "no-store",
    }).then((response) => {
      if (!response.ok) throw new Error("QR non disponibile. Verifica il tuo accesso.");
      return response.blob();
    }).then((blob) => {
      if (!active) return;
      objectUrl = URL.createObjectURL(blob);
      setQrSrc(objectUrl);
    }).catch((err) => {
      if (active) setQrError(err.message || "QR non disponibile.");
    });
    return () => {
      active = false;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [base, expanded, itemId]);

  const downloadPdf = async () => {
    if (busy || !itemId) return;
    setBusy(true);
    setPdfError("");
    try {
      const response = await fetch(`${base}/pdf`, {
        headers: { Authorization: `Bearer ${localStorage.getItem("da_token") || ""}` },
        cache: "no-store",
      });
      if (!response.ok) throw new Error("Download non disponibile. Verifica il tuo accesso.");
      const url = URL.createObjectURL(await response.blob());
      const a = document.createElement("a");
      a.href = url;
      a.download = "docuanalytics-priorita.pdf";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 4000);
    } catch (err) {
      setPdfError(err.message || "Errore durante il download.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <section className={`ws-qrpdf ${expandedInitially ? "ws-qrpdf-full" : "ws-qrpdf-compact"}`} data-testid={testId}>
      {expandedInitially && <h3 className="ws-h3">QR e PDF del documento</h3>}
      <button type="button" className="ws-priority-qr-link ws-qrpdf-trigger" aria-expanded={expanded}
        aria-label={expanded ? "Nascondi QR / PDF" : "Mostra QR / PDF"}
        onClick={() => setExpanded((value) => !value)} data-testid={`${testId}-toggle`}>
        <QrCode size={17} /> {expandedInitially ? (expanded ? "Nascondi QR" : "Mostra QR") : "QR / PDF"}
      </button>
      {expanded && (
        <div className="ws-qrpdf-content">
          <p className="ws-muted"><LockKeyhole size={14} style={{ display: "inline", verticalAlign: "middle" }} /> QR dedicato a questa scheda. Il collegamento richiede l'accesso autorizzato.</p>
          {qrError && <p className="ws-error" role="alert">{qrError}</p>}
          {!qrSrc && !qrError && <p className="ws-muted">Caricamento QR…</p>}
          {qrSrc && <img className="ws-qrpdf-image" src={qrSrc} alt="QR protetto di questa priorità" width="174" height="174" data-testid={`${testId}-image`} />}
          <div className="ws-qrpdf-actions">
            <button type="button" className="ws-priority-qr-link ws-qrpdf-download" onClick={downloadPdf} disabled={busy} data-testid={`${testId}-pdf`}>
              <Download size={16} /> {busy ? "Preparazione…" : "Scarica PDF"}
            </button>
            <Link to={detailPath} className="ws-link" data-testid={`${testId}-detail`}>Apri scheda protetta</Link>
          </div>
          {pdfError && <p className="ws-error" role="alert">{pdfError}</p>}
        </div>
      )}
    </section>
  );
}
